import ast

def process(parse_html_full):
    df = parse_html_full[parse_html_full['table_idx'] == 1].copy()

    records = []
    for _, row in df.iterrows():
        cells = ast.literal_eval(row['cells'])
        if len(cells) < 3:
            continue
        name = cells[0]
        # Skip header row
        if 'metropolitan' in name.lower() or 'msa' not in name.lower():
            # Check if it's actually a data row by seeing if pop looks numeric
            pass
        pop_2024_str = cells[1]
        pop_2020_str = cells[2]
        # Try to parse populations
        try:
            pop_2024 = int(pop_2024_str.replace(',', '').replace('\u2212', '-'))
            pop_2020 = int(pop_2020_str.replace(',', '').replace('\u2212', '-'))
            records.append({'msa_name': name, 'pop_2024': pop_2024, 'pop_2020': pop_2020})
        except (ValueError, AttributeError):
            continue

    return pd.DataFrame(records)

